INSERT INTO `agenda_2030` VALUES (1,'Porre fine ad ogni forma di povertà nel mondo'),(3,'Assicurare la salute e il benessere per tutti e per tutte le età'),(4,'Fornire un\'educazione di qualità, equa ed inclusiva, e opportunità di apprendimento per tutti'),(5,'Raggiungere l\'uguaglianza di genere ed emancipare tutte le donne e le ragazze'),(6,'Garantire a tutti la disponibilità e la gestione sostenibile dell\'acqua e delle strutture igienico sanitarie'),(7,'Assicurare a tutti l\'accesso a sistemi di energia economici, affidabili, sostenibili e moderni'),(8,'Incentivare una crescita economica, duratura, inclusiva e sostenibile, un\'occupazione piena e produttiva ed un lavoro dignitoso per tutti'),(9,'Costruire una infrastruttura resiliente e promuovere l\'innovazione e una industrializzazione equa, responsabile e sostenibile'),(10,'Ridurre le disuguaglianze all\'interno e fra le Nazioni'),(11,'Rendere le città e gli insediamenti umani inclusivi, sicuri, resilienti e sostenibili'),(12,'Garantire modelli sostenibili di produzione e di consumo'),(13,'Adottare misure urgenti per combattere il cambiamento climatico e le sue conseguenze'),(14,'Conservare e utilizzare in modo sostenibile gli oceani, i mari e le risorse marine per uno sviluppo sostenibile'),(16,'Promuovere società pacifiche e inclusive per uno sviluppo sostenibile; rendere disponibile l\'accesso alla giustizia per tutti e creare organismi efficaci, responsabili e inclusivi a tutti i livelli');
/*!40000 ALTER TABLE `agenda_2030` ENABLE KEYS */;
UNLOCK TABLES;

