INSERT INTO `campo_intervento` VALUES (1,'001 - Investimenti in capitale fisso, comprese le infrastrutture per la ricerca, in microimprese direttamente connessi alle attivita\' di ricerca e innovazione'),(2,'003 - Investimenti in capitale fisso, comprese le infrastrutture per la ricerca, in centri di ricerca pubblici e nell\'istruzione superiore pubblica direttamente connessi alle attivita\' di ricerca e innovazione'),(3,'006 - Investimenti in beni immateriali in centri di ricerca pubblici e nell\'istruzione superiore pubblica direttamente connessi alle attivita\' di ricerca e innovazione'),(4,'007 - Attivita\' di ricerca e innovazione in microimprese, comprese le attivita\' in rete (ricerca industriale, sviluppo sperimentale, studi di fattibilita\')'),(5,'008 - Attivita\' di ricerca e innovazione in PMI, comprese le attivita\' in rete'),(6,'009 - Attivita\' di ricerca e innovazione in centri di ricerca pubblici, istituti di istruzione superiore e centri di competenze, comprese le attivita\' in rete (ricerca industriale, sviluppo sperimentale, studi di fattibilita\')'),(7,'009BIS - Investimenti in attivita\' di R&I connesse al digitale (compresi centri di ricerca di eccellenza, ricerca industriale, sviluppo sperimentale, studi di fattibilita\', acquisizione di attivi fissi o immateriali per attivita\' di R&I connesse al digitale)'),(8,'009BIS - Investimenti in attivita\' di R&I connesse al digitale (compresi i centri di ricerca di eccellenza, la ricerca industriale, lo sviluppo sperimentale, gli studi di fattibilita\', l\'acquisizione di attivita\' fisse o immateriali per attivita\' di R&I connesse al digitale)'),(9,'010 - Digitalizzazione delle PMI (compreso il commercio elettronico, l\'e- business e i processi aziendali in rete, i poli di innovazione digitale, i laboratori viventi, gli imprenditori del web, le start-up nel settore delle TIC e il B2B)'),(10,'010 - Digitalizzazione delle PMI (compreso il commercio elettronico, l\'e-business e i processi aziendali in rete, i poli di innovazione digitale, i laboratori viventi, gli imprenditori del web, le start-up nel settore delle TIC e il B2B)'),(11,'011 - Soluzioni TIC, servizi elettronici, applicazioni per l\'amministrazione'),(12,'011BIS - Soluzioni TIC, servizi elettronici, applicazioni per l\'amministrazione conformemente ai criteri di riduzione delle emissioni di gas a effetto serra o di efficienza energetica'),(13,'011QUATER - Digitalizzazione dei sistemi di giustizia'),(14,'011QUATER - Digitalizzazione dei sistemi giudiziari'),(15,'011TER - Applicazione del regime europeo di identita\' digitale per uso pubblico e privato'),(16,'012 - Applicazioni e servizi e informatici per le competenze digitali e l\'inclusione digitale'),(17,'013 - Applicazioni e servizi e informatici di assistenza sanitaria online (compresi l\'e-Care, Internet delle cose per l\'attivita\' fisica e la domotica per categorie deboli)'),(18,'013 - Applicazioni e servizi e informatici di assistenza sanitaria online (compresi l\'e-Care, l\'Internet delle cose per l\'attivita\' fisica e la domotica per categorie deboli)'),(19,'015 - Sviluppo dell\'attivita\' delle PMI e internazionalizzazione, compresi gli investimenti produttivi'),(20,'016 - Sviluppo delle competenze per la specializzazione intelligente, la transizione industriale, l\'imprenditorialita\' e l\'adattabilita\' delle imprese ai cambiamenti'),(21,'019 - Sostegno ai poli di innovazione, anche tra imprese, organismi di ricerca e autorita\' pubbliche e reti di imprese a beneficio pr incipalmente delle PMI'),(22,'019 -Sostegno ai poli di innovazione, anche tra imprese, organismi di ricerca e autorita\' pubbliche e reti di imprese a beneficio pri ncipalmente delle PMI'),(23,'021 - Trasferimento di tecnologie e cooperazione tra le imprese, i centri di ricerca e il settore dell\'istruzione superiore'),(24,'021BIS - Sostegno alla produzione e alla distribuzione di contenuti digitali'),(25,'021QUATER - Investimenti in tecnologie avanzate quali: capacita\' di calcolo ad alte prestazioni e di calcolo quantistico/capacita\' di c omunicazione quantistica (compresa la crittografia quantistica) - progettazione, produzione e integrazione dei sistemi di microelettronica; la prossima generazione di dati, cloud e capacita\' europee all\'avanguardia (infrastrutture, piattaforme e servizi); realta\' virtuale e aumentata, Deeptech e altre tecnologie digitali avanzate. Investimenti volti a garantire la sicurezza della catena di approvvigionamento digitale.'),(26,'021QUINQUIES - Sviluppo e diffusione di tecnologie, misure e strutture di supporto per la cibersicurezza per gli utenti del settore pubblico e privato.'),(27,'022 - Processi di ricerca e di innovazione, trasferimento di tecnologie e cooperazione tra imprese incentrate sull\'economia a basse emissioni di carbonio, sulla resilienza e sull\'adattamento ai cambiamenti climatici'),(28,'023 - Processi di ricerca e innovazione, trasferimento di tecnologie e cooperazione tra imprese incentrate sull\'economia circolare'),(29,'024 - Efficienza energetica e progetti dimostrativi nelle PMI e misure di sostegno'),(30,'025 - Rinnovo della dotazione di alloggi sul piano dell\'efficienza energetica, progetti dimostrativi e misure di sostegno'),(31,'025BIS - Rinnovo della dotazione di alloggi sul piano dell\'efficienza energetica, progetti dimostrativi e misure di sostegno conformi ai criteri di efficienza energetica'),(32,'025TER - Costruzione di nuovi edifici efficienti sotto il profilo energetico'),(33,'026 - Rinnovo di infrastrutture pubbliche sul piano dell\'efficienza energetica e misure relative all\'efficienza energetica per tali infrastrutture, progetti dimostrativi e misure di sostegno'),(34,'027 - Sostegno alle imprese che forniscono servizi che contribuiscono all\'economia a basse emissioni di carbonio e alla resilienza ai cambiamenti climatici, comprese le misure di sensibilizzazione'),(35,'028 - Energia rinnovabile: energia eolica'),(36,'029 - Energia rinnovabile: solare'),(37,'030BIS - Energia rinnovabile: biomassa con elevate riduzioni di gas a effetto serra'),(38,'032 - Altre energie rinnovabili (compresa l\'energia geotermica)'),(39,'033 - Sistemi energetici intelligenti (comprese le reti intelligenti e i sistemi TIC) e relativo stoccaggio'),(40,'034BIS0 - Cogenerazione ad alto rendimento, teleriscaldamento efficiente e teleraffreddamento con basse emissioni del ciclo di vita'),(41,'035 - Misure di adattamento ai cambiamenti climatici e prevenzione e gestione dei rischi connessi al clima: inondazioni (comprese le azioni di sensibilizzazione, la protezione civile, i sistemi e le infrastrutture di gestione delle catastrofi e gli approcci basati sugli ecosistemi)'),(42,'037 - Misure di adattamento ai cambiamenti climatici e prevenzione e gestione dei rischi connessi al clima: altri rischi, per esempio tempeste e siccita\' (comprese le azioni di sensibilizzazione, la protezione civile, i sistemi e le infrastrutture di gestione delle catastrofi e gli approcci basati sugli ecosistemi)'),(43,'038 - Prevenzione e gestione dei rischi naturali non connessi al clima (come i terremoti) e dei rischi collegati alle attivita\' umane (per esempio incidenti tecnologici), comprese le azioni di sensibilizzazione, la protezione civile, i sistemi e le infrastrutture per la gestione delle catastrofi e gli approcci basati sugli ecosistemi'),(44,'039BIS - Fornitura di acqua per il consumo umano (infrastrutture di estrazione, trattamento, stoccaggio e distribuzione, misure di e fficienza idrica, approvvigionamento di acqua potabile) conformemente ai criteri di efficienza'),(45,'040 - Gestione delle risorse idriche e loro conservazione (compresa la gestione dei bacini idrografici, misure specifiche di adattamento ai cambiamenti climatici, riutilizzo, riduzione delle perdite)'),(46,'041BIS - Raccolta e trattamento delle acque reflue conformemente ai criteri di efficienza energetica'),(47,'042 - Gestione dei rifiuti domestici: misure di prevenzione, minimizzazione, smistamento, riutilizzo e riciclaggio'),(48,'046 - Recupero dei siti industriali e dei terreni contaminati'),(49,'047 - Sostegno ai processi di produzione rispettosi dell\'ambiente e all\'efficienza delle risorse nelle PMI'),(50,'048 - Misure per la qualita\' dell\'aria e la riduzione del rumore'),(51,'049 - Protezione, ripristino e uso sostenibile dei siti Natura 2000'),(52,'050 - Tutela della natura e della biodiversita\', patrimonio e risorse naturali, infrastrutture verdi e blu'),(53,'051 - Reti a banda larga ad altissima capacita\' (reti dorsali/di backhaul)'),(54,'051 - TIC: reti a banda larga ad altissima capacita\' (reti dorsali/di backhaul)'),(55,'054 - TIC: reti a banda larga ad altissima capacita\' (accesso/linea locale con prestazioni equivalenti a un\'installazione in fibra ottica fino alla stazione di base per comunicazioni senza fili avanzate)'),(56,'054TER - Connettivita\' mobile dei dati con un\'ampia copertura territoriale'),(57,'055 - Altre tipologie di infrastrutture TIC (compresi risorse/impianti informatici di grandi dimensioni, centri di dati, sensori e altri dispositivi wireless)'),(58,'055 - TIC: altre tipologie di infrastrutture TIC (compresi risorse/impianti informatici di grandi dimensioni, centri di dati, sensori e altri dispositivi wireless)'),(59,'055BIS - Altre tipologie di infrastrutture TIC (compresi risorse/impianti informatici di grandi dimensioni, centri di dati, sensori e altri dispositivi wireless) conformemente ai criteri di riduzione delle emissioni di gas a effetto serra o di efficienza energetica.'),(60,'064 - Linee ferroviarie di nuova costruzione o ristrutturate- rete centrale TEN-T'),(61,'065 - Linee ferroviarie di nuova costruzione o ristrutturate- rete globale TEN-T'),(62,'068 - Linee ferroviarie ricostruite o ammodernate - rete globale TEN-T'),(63,'069 - Altre linee ferroviarie ricostruite o ammodernate'),(64,'071 - Sistema europeo di gestione del traffico ferroviario (ERTMS)'),(65,'072BIS - Infrastrutture ferroviarie mobili a zero emissioni/elettriche'),(66,'073 - Infrastrutture di trasporto urbano pulito'),(67,'074 - Materiale rotabile di trasporto urbano pulito'),(68,'075 - Infrastrutture ciclistiche'),(69,'077 - Infrastrutture per combustibili alternativi'),(70,'078 - Trasporti multimodali (TEN-T)'),(71,'079 - Trasporto multimodale (non urbano)'),(72,'084 - Digitalizzazione dei trasporti: altri modi di trasporto'),(73,'084BIS - Digitalizzazione dei trasporti se dedicato in parte alla riduzione delle emissioni di gas a effetto serra: altri modi di tr asporto'),(74,'085 - Infrastrutture per l\'educazione e la cura della prima infanzia'),(75,'086 - Infrastrutture per l\'istruzione primaria e secondaria'),(76,'087 - Infrastrutture per l\'istruzione terziaria'),(77,'089 - Infrastrutture abitative destinate ai migranti, ai rifugiati e alle persone che fanno domanda di protezione internazionale o che godono di protezione internazionale'),(78,'090 - Infrastrutture abitative destinate ai migranti (diversi dai rifugiati e dalle persone che fanno domanda di protezione internazionale o che godono di protezione internazionale)'),(79,'091 - Altre infrastrutture sociali che contribuiscono all\'inclusione sociale nella comunita\''),(80,'092 - Infrastrutture per la sanita\''),(81,'093 - Attrezzature sanitarie'),(82,'095 - Digitalizzazione delle cure sanitarie'),(83,'097 - Misure volte a migliorare l\'accesso al mercato del lavoro'),(84,'099 - Sostegno specifico per l\'occupazione giovanile e l\'integrazione socio- economica dei giovani'),(85,'099 - Sostegno specifico per l\'occupazione giovanile e l\'integrazione socio-economica dei giovani'),(86,'100 - Sostegno al lavoro autonomo e all�avvio di imprese'),(87,'101 - Sostegno all\'economia sociale e alle imprese sociali'),(88,'103 - Sostegno all\'incontro della domanda e dell\'offerta e alle transizioni'),(89,'104 - Sostegno alla mobilita\' dei lavoratori'),(90,'105 - Misure volte a promuovere la partecipazione delle donne al mercato del lavoro e a ridurre la segregazione di genere nel mercato del lavoro'),(91,'108 - Sostegno allo sviluppo di competenze digitali'),(92,'112 - Sostegno all\'istruzione primaria e secondaria (infrastrutture escluse)'),(93,'113 - Sostegno all\'istruzione terziaria (infrastrutture escluse)'),(94,'115 - Misure volte a promuovere le pari opportunita\' e la partecipazione attiva alla societa\''),(95,'123 - Misure volte a migliorare l\'accessibilita\', l\'efficacia e la resilienza dei sistemi sanitari (infrastrutture escluse)'),(96,'125 - Misure volte a modernizzare i sistemi di protezione sociale, compresa la promozione dell\'accesso alla protezione sociale'),(97,'126 - Misure volte a promuovere l\'integrazione sociale delle persone a rischio di poverta\' o di esclusione sociale, compresi gli indigenti e i bambini'),(98,'128 - Protezione, sviluppo e promozione dei beni turistici pubblici e dei servizi turistici'),(99,'129 - Protezione, sviluppo e promozione del patrimonio culturale e dei servizi culturali'),(100,'131 - Riqualificazione materiale e sicurezza degli spazi pubblici'),(101,'143 - Rafforzamento della capacita\' delle autorita\' dello Stato membro, dei beneficiari e dei partner pertinenti');
