--
-- Table structure for table `progetto`
--

DROP TABLE IF EXISTS `progetto`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `progetto` (
  `CUP` varchar(15) NOT NULL,
  `Titolo` varchar(512) DEFAULT NULL,
  `Codice_locale_progetto` varchar(15) DEFAULT NULL,
  `ID_Unità_organizzativa` int DEFAULT NULL,
  `Codice_submisura` varchar(15) DEFAULT NULL,
  `Cod_cup_natura` int DEFAULT NULL,
  `ID_regione` varchar(10) DEFAULT NULL,
  `ID_provincia` varchar(10) DEFAULT NULL,
  `ID_comune` varchar(10) DEFAULT NULL,
  `Indirizzo` varchar(128) DEFAULT NULL,
  `CF_programmaore` varchar(32) DEFAULT NULL,
  `CF_attuatore` varchar(32) DEFAULT NULL,
  `CF_beneficiario` varchar(32) DEFAULT NULL,
  PRIMARY KEY (`CUP`),
  KEY `ID_comune_idx` (`ID_comune`),
  KEY `ID_unità_organizzativa_idx` (`ID_Unità_organizzativa`),
  KEY `ID_unità_organizzativa3_idx` (`ID_Unità_organizzativa`),
  KEY `Codice_submisura_idx` (`Codice_submisura`),
  KEY `Cod_cup_natura_idx` (`Cod_cup_natura`),
  KEY `ID_provincia` (`ID_provincia`),
  KEY `ID_regione` (`ID_regione`),
  KEY `CF_programmatore_idx` (`CF_programmaore`),
  KEY `CF_attuatore1_idx` (`CF_attuatore`),
  KEY `CF_beneficiario1_idx` (`CF_beneficiario`),
  CONSTRAINT `CF_attuatore1` FOREIGN KEY (`CF_attuatore`) REFERENCES `ente` (`CF_ente`),
  CONSTRAINT `CF_beneficiario1` FOREIGN KEY (`CF_beneficiario`) REFERENCES `ente` (`CF_ente`),
  CONSTRAINT `CF_programmatore1` FOREIGN KEY (`CF_programmaore`) REFERENCES `ente` (`CF_ente`),
  CONSTRAINT `Cod_cup_natura` FOREIGN KEY (`Cod_cup_natura`) REFERENCES `natura_progetto` (`Codice_CUP_natura`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `Codice_submisura` FOREIGN KEY (`Codice_submisura`) REFERENCES `submisura` (`Codice_submisura`),
  CONSTRAINT `ID_comune` FOREIGN KEY (`ID_comune`) REFERENCES `comune` (`ID_comune`),
  CONSTRAINT `ID_unità_organizzativa3` FOREIGN KEY (`ID_Unità_organizzativa`) REFERENCES `unità_organizzativa` (`ID_Unità_organizzativa`),
  CONSTRAINT `progetto_ibfk_1` FOREIGN KEY (`ID_provincia`) REFERENCES `provincia` (`ID_provincia`),
  CONSTRAINT `progetto_ibfk_2` FOREIGN KEY (`ID_regione`) REFERENCES `regione` (`iD_regione`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;
/*!40101 SET character_set_client = @saved_cs_client */;

