--
-- Table structure for table `programma`
--

DROP TABLE IF EXISTS `programma`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `programma` (
  `Codice_programma` varchar(32) NOT NULL,
  `Nome_programma` varchar(512) DEFAULT NULL,
  `Importo` double DEFAULT NULL,
  `Descrizione_programma` varchar(2048) DEFAULT NULL,
  `Programma_esclusivo_cofinanziato` varchar(64) DEFAULT NULL,
  `CF_amministrazione_pubblica` varchar(16) DEFAULT NULL,
  `Codice_componente` varchar(4) DEFAULT NULL,
  PRIMARY KEY (`Codice_programma`),
  KEY `CF_amministrazione_pubblica_idx` (`CF_amministrazione_pubblica`),
  KEY `Codice_componente_idx` (`Codice_componente`),
  CONSTRAINT `CF_amministrazione_pubblica2` FOREIGN KEY (`CF_amministrazione_pubblica`) REFERENCES `amministrazione_pubblica` (`CF_amministrazione_pubblica`),
  CONSTRAINT `Codice_componente2` FOREIGN KEY (`Codice_componente`) REFERENCES `componente` (`Codice_componente`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;
/*!40101 SET character_set_client = @saved_cs_client */;

