CREATE TABLE `traguardo` (
  `NR_SEQ_M&T` varchar(16) NOT NULL,
  `Ulteriori_info` varchar(512) DEFAULT NULL,
  `Meccanismo_di_verifica` varchar(512) DEFAULT NULL,
  `ITA_UE` varchar(3) DEFAULT NULL,
  `Descrizione_traguardo` varchar(512) DEFAULT NULL,
  `Principali_evidenze` varchar(512) DEFAULT NULL,
