  PRIMARY KEY (`Indicator`),
  KEY `ID_goal_idx` (`ID_goal`),
  CONSTRAINT `ID_goal` FOREIGN KEY (`ID_goal`) REFERENCES `agenda_2030` (`ID_goal`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;
